ax-keyword\u0022\u003Estatic\u003C/span\u003E \u003Cspan class=\u0022syntax-keyword\u0022\u003Easync\u003C/span\u003E \u003Cspan class=\u0022syntax-type\u0022\u003EValueTask\u003C/span\u003E\u0026lt;\u003Cspan class=\u0022syntax-type\u0022\u003ET\u003C/span\u003E\u0026gt; \u003Cspan class=\u0022syntax-type\u0022\u003ETryCatch\u003C/span\u003E\u0026lt;\u003Cspan class=\u0022syntax-type\u0022\u003ET\u003C/span\u003E\u0026gt;(\u003Cspan class=\u0022syntax-type\u0022\u003EFunc\u003C/span\u003E\u0026lt;\u003Cspan class=\u0022syntax-type\u0022\u003EValueTask\u003C/span\u003E\u0026lt;\u003Cspan class=\u0022syntax-type\u0022\u003ET\u003C/span\u003E\u0026gt;\u0026gt; operation)\n    {\n        \u003Cspan class=\u0022syntax-keyword\u0022\u003Etry\u003C/span\u003E\n        {\n            \u003Cspan class=\u0022syntax-keyword\u0022\u003Ereturn\u003C/span\u003E \u003Cspan class=\u0022syntax-keyword\u0022\u003Eawait\u003C/span\u003E operation();\n        }\n        \u003Cspan class=\u0022syntax-keyword\u0022\u003Ecatch\u003C/span\u003E (\u003Cspan class=\u0022syntax-type\u0022\u003EArgumentException\u003C/span\u003E innerException)\n        {\n            \u003Cspan class=\u0022syntax-keyword\u0022\u003Ethrow\u003C/span\u003E \u003Cspan class=\u0022syntax-keyword\u0022\u003Enew\u003C/span\u003E \u003Cspan class=\u0022syntax-type\u0022\u003EStudentServiceValidationException\u003C/span\u003E(innerException);\n        }\n        \u003Cspan class=\u0022syntax-keyword\u0022\u003Ecatch\u003C/span\u003E (\u003Cspan class=\u0022syntax-type\u0022\u003EInvalidOperationException\u003C/span\u003E innerException)\n        {\n            \u003Cspan class=\u0022syntax-keyword\u0022\u003Ethrow\u003C/span\u003E \u003Cspan class=\u0022syntax-keyword\u0022\u003Enew\u003C/span\u003E \u003Cspan class=\u0022syntax-type\u0022\u003EStudentServiceDependencyException\u003C/span\u003E(innerException);\n        }\n        \u003Cspan class=\u0022syntax-keyword\u0022\u003Ecatch\u003C/span\u003E (\u003Cspan class=\u0022syntax-type\u0022\u003EException\u003C/span\u003E innerException)\n        {\n            \u003Cspan class=\u0022syntax-keyword\u0022\u003Ethrow\u003C/span\u003E \u003Cspan class=\u0022syntax-keyword\u0022\u003Enew\u003C/span\u003E \u003Cspan class=\u0022syntax-type\u0022\u003EStudentServiceException\u003C/span\u003E(innerException);\n        }\n    }\n}\u003C/code\u003E\u003C/pre\u003E\u003Ch2\u003EGood code example\u003C/h2\u003E\u003Cpre\u003E\u003Ccode class=\u0022language-csharp\u0022\u003E\u003Cspan class=\u0022syntax-comment\u0022\u003E// Follows STX0009\u003C/span\u003E\n\u003Cspan class=\u0022syntax-comment\u0022\u003E// StudentService.cs\u003C/span\u003E\n\u003Cspan class=\u0022syntax-keyword\u0022\u003Einternal\u003C/span\u003E partial \u003Cspan class=\u0022syntax-keyword\u0022\u003Eclass\u003C/span\u003E \u003Cspan class=\u0022syntax-type\u0022\u003EStudentService\u003C/span\u003E(\u003Cspan class=\u0022syntax-type\u0022\u003EIStudentBroker\u003C/span\u003E studentBroker)\n    : \u003Cspan class=\u0022syntax-type\u0022\u003EIStudentService\u003C/span\u003E\n{\n    \u003Cspan class=\u0022syntax-keyword\u0022\u003Epublic\u003C/span\u003E \u003Cspan class=\u0022syntax-type\u0022\u003EValueTask\u003C/span\u003E\u0026lt;\u003Cspan class=\u0022syntax-type\u0022\u003EStudent\u003C/span\u003E\u0026gt; \u003Cspan class=\u0022syntax-type\u0022\u003EAddStudentAsync\u003C/span\u003E(\u003Cspan class=\u0022syntax-type\u0022\u003EStudent\u003C/span\u003E newStudent) =\u0026gt;\n        \u003Cspan class=\u0022syntax-type\u0022\u003ETryCatch\u003C/span\u003E\u0026lt;\u003Cspan class=\u0022syntax-type\u0022\u003EStudent\u003C/span\u003E\u0026gt;(operation: \u003Cspan class=\u0022syntax-keyword\u0022\u003Easync\u003C/span\u003E () =\u0026gt;\n        {\n            \u003Cspan class=\u0022syntax-keyword\u0022\u003Eawait\u003C/span\u003E \u003Cspan class=\u0022syntax-type\u0022\u003EValidateStudentOnAdd\u003C/span\u003E(newStudent);\n            \u003Cspan class=